// Verilator harness for the emitted `silicon_elab_top.sv`
// (Obend.Lower.SiliconElabFabric.emitSiliconElabFabricSV, regenerated by `obend hardware emit-silicon-sv`).
//
// Expected values are not literals here: `silicon_elab_golden.txt` is written by
// `obend-emit-sv golden-silicon-kernel` from the Lean model (`runVerilatorCoSimModel`) and this
// harness asserts the Verilated RTL reproduces them. Hand-written file; the DUT is not.
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <map>
#include <string>

#include "Vsilicon_elab_top.h"
#include "verilated.h"
#include "verilated_vcd_c.h"

namespace {

std::map<std::string, std::string> read_golden(const char* path) {
    std::map<std::string, std::string> kv;
    std::ifstream in(path);
    std::string line;
    while (std::getline(in, line)) {
        if (line.empty() || line[0] == '#') continue;
        auto eq = line.find('=');
        if (eq == std::string::npos) continue;
        kv[line.substr(0, eq)] = line.substr(eq + 1);
    }
    return kv;
}

uint64_t golden_u64(const std::map<std::string, std::string>& g, const char* key) {
    auto it = g.find(key);
    if (it == g.end()) { std::fprintf(stderr, "[FATAL] golden key missing: %s\n", key); std::exit(2); }
    return std::strtoull(it->second.c_str(), nullptr, 10);
}

// 88-bit PackedNodeWord: [87:84] tag, [82] hasLooseBVar, [81] hasMVar, [31:16] h1, [15:0] h0.
void set_word88(VlWide<3>& w, unsigned tag, bool loose, bool mvar, unsigned h1, unsigned h0) {
    uint64_t lo = (uint64_t(h0) & 0xFFFF) | ((uint64_t(h1) & 0xFFFF) << 16);
    uint32_t hi = ((tag & 0xF) << 20) | ((loose ? 1u : 0u) << 18) | ((mvar ? 1u : 0u) << 17);
    w[0] = uint32_t(lo & 0xFFFFFFFFu);
    w[1] = uint32_t(lo >> 32);
    w[2] = hi;  // bits [87:64] -> [23:0]
}

struct Sim {
    Vsilicon_elab_top* top;
    VerilatedVcdC* tfp;
    uint64_t t = 0;
    uint64_t fails = 0;

    explicit Sim(const char* vcd) {
        top = new Vsilicon_elab_top;
        tfp = new VerilatedVcdC;
        top->trace(tfp, 99);
        tfp->open(vcd);
    }
    ~Sim() { tfp->close(); delete tfp; delete top; }

    void tick() {
        top->clk = 0; top->eval(); tfp->dump(t++);
        top->clk = 1; top->eval(); tfp->dump(t++);
    }
    void idle_inputs() {
        top->dma_we = 0; top->dma_addr = 0;
        top->dma_wdata[0] = top->dma_wdata[1] = top->dma_wdata[2] = 0;
        top->elab_start = 0; top->focus_handle_in = 0; top->rhs_handle_in = 0;
        top->pkt_epoch_in = 1; top->pinned_epoch_in = 1; top->pin_valid_in = 1;
        top->icap_phase_in = 0; top->icap_new_gain_in = 0; top->icap_new_offset_in = 0;
        top->icap_expected_digest_in = 0; top->icap_computed_digest_in = 0;
        top->lut_arg_in = 10;
        top->sorry_flag_in = 0; top->is_sort_decl_in = 0;
        top->expr_tag_in = 0; top->arg0_code_in = 0; top->arg1_code_in = 0; top->expected_ty_code_in = 0;
    }
    void reset() {
        idle_inputs();
        top->rst_n = 0; top->eval(); tick(); tick();
        top->rst_n = 1; tick();
    }
    void dma(unsigned addr, unsigned tag, bool loose, bool mvar, unsigned h1, unsigned h0) {
        top->dma_we = 1; top->dma_addr = addr;
        set_word88(top->dma_wdata, tag, loose, mvar, h1, h0);
        tick();
        top->dma_we = 0;
    }
    void check(bool ok, const char* what) {
        if (!ok) { std::fprintf(stderr, "[FAIL] %s\n", what); fails++; }
        else std::printf("[ok] %s\n", what);
    }
};

} // namespace

int main(int argc, char** argv) {
    Verilated::commandArgs(argc, argv);
    Verilated::randReset(2);
    Verilated::traceEverOn(true);
    const char* vcd_path = (argc > 1) ? argv[1] : "silicon_elab_wave.vcd";
    const char* golden_path = (argc > 2) ? argv[2] : "silicon_elab_golden.txt";
    auto g = read_golden(golden_path);
    const uint64_t g_epoch1 = golden_u64(g, "epoch1_lut_out");
    const uint64_t g_epoch2 = golden_u64(g, "epoch2_lut_out");
    const bool g_moved_pin = golden_u64(g, "moved_pin_fallback") != 0;
    const bool g_clamped = golden_u64(g, "dpr_glitch_free_clamped") != 0;
    const bool g_tooth = golden_u64(g, "tooth_mutant_refused") != 0;
    const bool g_sorry = golden_u64(g, "sorry_refused") != 0;

    Sim s(vcd_path);
    s.reset();

    // Zone 1: CAM words. 4 = lit 42 (tag 8, closed); 6 = lam (tag 5, body h1=4); 7 = app (tag 4, fn h0=6).
    s.dma(4, 8, false, false, 0, 42);
    s.dma(6, 5, false, false, 4, 0);
    s.dma(7, 4, false, false, 5, 6);
    s.dma(9, 4, false, true,  4, 8);   // an .app carrying an mvar (bit 81) for the scope filter

    // Closed-term beta bypass: start on handle 7, evaluate on the next cycle.
    s.top->elab_start = 1; s.top->focus_handle_in = 7; s.top->rhs_handle_in = 7;
    s.top->eval();
    s.check(s.top->handle_eq_hit == 1, "zone2: handle equality short-circuit (7 == 7)");
    s.tick();
    s.top->elab_start = 0;
    s.tick();
    s.check(s.top->closed_bypass_hit == 1 && s.top->whnf_handle_out == 4,
            "zone1: (lam . 42) 5 bypasses to body handle 4 in one evaluation cycle");

    // Zone 2 scope filter: focus 9 carries an mvar.
    s.top->elab_start = 1; s.top->focus_handle_in = 9; s.top->rhs_handle_in = 4; s.tick();
    s.top->elab_start = 0; s.top->eval();
    s.check(s.top->mvar_scope_clean == 0, "zone2: bit-81 mvar scope filter refuses handle 9");

    // Zone 3 epoch-1 LUT hit, value from the Lean model's epoch-1 tile (gain 4, offset 2, arg 10).
    s.top->pkt_epoch_in = 1; s.top->pinned_epoch_in = 1; s.top->pin_valid_in = 1; s.top->lut_arg_in = 10;
    s.top->eval();
    s.check(s.top->used_fast_path == 1 && s.top->routed_to_zone1 == 0 && s.top->lut_val_out == g_epoch1,
            "zone3: epoch-1 LUT fast path equals Lean golden epoch1_lut_out");

    // moved_pin_blocks: packet epoch 2 against pinned epoch 1 falls back the same cycle.
    s.top->pkt_epoch_in = 2; s.top->eval();
    const bool hw_moved_pin = (s.top->used_fast_path == 0) && (s.top->routed_to_zone1 == 1);
    s.check(hw_moved_pin == g_moved_pin, "zone3: moved-pin fallback matches Lean golden");
    s.top->pkt_epoch_in = 1;

    // 3-phase tile swap: isolate, load (gain 6, offset 10, digest 0x600A), release on digest match.
    s.top->icap_phase_in = 1; s.tick();
    s.top->icap_phase_in = 0; s.top->eval();
    const bool held_during_isolate = (s.top->lut_val_out == g_epoch1) && (s.top->used_fast_path == 0);
    s.top->icap_phase_in = 2; s.top->icap_new_gain_in = 6; s.top->icap_new_offset_in = 10;
    s.top->icap_computed_digest_in = 0x600A; s.top->icap_expected_digest_in = 0x600A; s.tick();
    s.top->icap_phase_in = 0; s.top->eval();
    const bool held_during_load = (s.top->lut_val_out == g_epoch1);
    // a corrupt digest must keep the fence up
    s.top->icap_phase_in = 3; s.top->icap_expected_digest_in = 0xDEAD; s.tick();
    s.top->icap_phase_in = 0; s.top->eval();
    const bool held_on_bad_digest = (s.top->lut_val_out == g_epoch1);
    s.top->icap_phase_in = 3; s.top->icap_expected_digest_in = 0x600A; s.tick();
    s.top->icap_phase_in = 0; s.top->eval();
    const bool released = (s.top->lut_val_out == g_epoch2) && (s.top->used_fast_path == 1);
    s.check((held_during_isolate && held_during_load && held_on_bad_digest && released) == g_clamped,
            "zone3: fence holds through isolate/load/bad-digest and releases to Lean golden epoch2_lut_out");

    // Zone 4: const idNat (tag 3, sym 2) : Nat -> Nat (code 17) accepted.
    s.top->expr_tag_in = 3; s.top->arg0_code_in = 2; s.top->arg1_code_in = 0; s.top->expected_ty_code_in = 17;
    s.top->elab_start = 1; s.tick(); s.top->elab_start = 0;
    s.check(s.top->done_out == 1 && s.top->accepted_out == 1 && s.top->status_tag_out == 1 &&
            s.top->inferred_ty_code_out == 17, "zone4: idNat : Nat -> Nat accepted (status 1)");
    // #tooth mutant: Bool.true (sym 5 -> code 5) claimed at Nat (code 1) -> refused, status 2.
    s.top->arg0_code_in = 5; s.top->expected_ty_code_in = 1; s.top->elab_start = 1; s.tick(); s.top->elab_start = 0;
    const bool hw_tooth = (s.top->accepted_out == 0) && (s.top->status_tag_out == 2);
    s.check(hw_tooth == g_tooth, "zone4: ill-typed mutant refused matches Lean golden");
    // sorryAx contamination -> status 0.
    s.top->arg0_code_in = 2; s.top->expected_ty_code_in = 17; s.top->sorry_flag_in = 1;
    s.top->elab_start = 1; s.tick(); s.top->elab_start = 0; s.top->sorry_flag_in = 0;
    const bool hw_sorry = (s.top->accepted_out == 0) && (s.top->status_tag_out == 0);
    s.check(hw_sorry == g_sorry, "zone4: sorryAx refused matches Lean golden");
    // universe mismatch flag -> status 3.
    s.top->arg0_code_in = 5; s.top->expected_ty_code_in = 1; s.top->is_sort_decl_in = 1;
    s.top->elab_start = 1; s.tick(); s.top->elab_start = 0; s.top->is_sort_decl_in = 0;
    s.check(s.top->status_tag_out == 3, "zone4: sort mismatch reports status 3");

    std::printf("{\"status\":\"%s\",\"fails\":%llu,\"vcd\":\"%s\",\"golden\":\"%s\"}\n",
                s.fails == 0 ? "PASS" : "FAIL", static_cast<unsigned long long>(s.fails), vcd_path, golden_path);
    return s.fails == 0 ? 0 : 1;
}
